syntax:
Pointer-to-member data declaration:

    type Class::*memberPointer;

Pointer-to-member data initialization:

    memberPointer = &Class::member;

Member access via object pointer:

    objectPointer->*memberPointer;

or

    (objectPointer->*memberPointer) = value;

code_example:
struct Point {
    int x;
    int y;
};

int main() {
    Point p;
    int Point::*ptrToY = &Point::y; // Pointer-to-member data initialized to 'y' offset
    p.*ptrToY = 42; // Assign value via pointer-to-member
    Point* pPtr = &p;
    pPtr->*ptrToY = 24; // Access and modify 'y' through pointer-to-member and object pointer
    return 0;
}
